content.text:
{
  "name": "非持久模式磁体线圈",
  "name_en": "Non-persistent Magnet Coil",
  "manufacturer": "",
  "description": "一种在非持久模式下工作的磁体线圈，用于在实验中产生和调节磁场。此类线圈通常通过外部电流源连续供电，常见于低温测量、量子器件表征及其他需要可控磁场偏置的实验。",
  "description_en": "A magnet coil operated in non-persistent mode, used to generate and adjust magnetic fields in laboratory experiments. This type of coil is typically driven continuously by an external current source and is commonly used in cryogenic measurements, quantum device characterization, and other setups requiring a controllable magnetic field bias.",
  "tag_hints": [
    "magnetic field control",
    "non-persistent magnet",
    "superconducting coil",
    "cryogenic experiments",
    "field-current conversion"
  ],
  "actions": [
    {
      "action_name": "auto-set_field",
      "description": "设置线圈产生的目标磁场。",
      "description_en": "Set the target magnetic field produced by the coil."
    },
    {
      "action_name": "auto-get_field",
      "description": "获取当前设定或对应的磁场值。",
      "description_en": "Get the current set or corresponding magnetic field value."
    },
    {
      "action_name": "auto-step_field_to_value",
      "description": "将磁场逐步调节到指定值。",
      "description_en": "Step or ramp the magnetic field to a specified value."
    },
    {
      "action_name": "auto-field_to_curr",
      "description": "将目标磁场换算为所需线圈电流。",
      "description_en": "Convert a target magnetic field to the required coil current."
    },
    {
      "action_name": "auto-curr_to_field",
      "description": "将线圈电流换算为对应磁场。",
      "description_en": "Convert coil current to the corresponding magnetic field."
    }
  ]
}

